import{_ as o,a0 as p,w as s,s as d,ao as l,I as i,x as t,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"5 个基于Linux命令行的文件下载和网站浏览工具 | LCTT x X-CMD","titleTemplate":false,"description":"5 个基于Linux命令行的文件下载和网站浏览工具 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 个基于Linux命令行的文件下载和网站浏览工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个基于Linux命令行的文件下载和网站浏览工具 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites","title":"5 个基于Linux命令行的文件下载和网站浏览工具","tag":"201505","desc":""},"relativePath":"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites.md","filePath":"[post].md"}'),m={name:"201505/20150407 5 Linux Command Line Based Tools for Downloading Files and Browsing Websites.md"};function w(c,e,h,T,u,g){const r=p("Link");return s(),d("div",null,[e[16]||(e[16]=l(`<h1 id="_5-个基于linux命令行的文件下载和网站浏览工具" tabindex="-1">5 个基于Linux命令行的文件下载和网站浏览工具 <a class="header-anchor" href="#_5-个基于linux命令行的文件下载和网站浏览工具" aria-label="Permalink to “5 个基于Linux命令行的文件下载和网站浏览工具”">​</a></h1><p>Linux命令行是GNU/Linux中最神奇迷人的部分，它是非常强大的工具。命令行本身功能多样，多种内建或者第三方的命令行应用使得Linux变得更加健壮和强大。Linux Shell支持多种不同类型的网络应用，无论是BT下载软件，专用下载器或者互联网冲浪。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Command-Line-Internet-Tools.jpg" alt="命令行互联网工具"></p><p><em>5个命令行互联网工具</em></p><p>这里我们介绍了5个很好的命令行互联网工具，它们非常有用，也很容易上手。</p><h3 id="_1-rtorrent" tabindex="-1">1. rTorrent <a class="header-anchor" href="#_1-rtorrent" aria-label="Permalink to “1. rTorrent”">​</a></h3><p>rTorrent是基于文本，用C++编写，追求高性能的Torrent客户端。支持大部分标准的Linux发行版，包括FreeBSD和Mac OS X。</p><h4 id="安装rtorrent" tabindex="-1">安装rTorrent <a class="header-anchor" href="#安装rtorrent" aria-label="Permalink to “安装rTorrent”">​</a></h4><pre><code># apt­-get install rtorrent    (基于 APT 的系统)
</code></pre><hr><pre><code># yum install rtorrent        (基于 YUM 的系统)
</code></pre><p>在终端中用下面的命令检查rtorrent是否正确安装</p><pre><code># rtorrent
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/rTorrent.jpeg" alt="命令行torrent下载器"></p><p><em>rTorrent命令行工具</em></p><h4 id="rtorrent的功能" tabindex="-1">rTorrent的功能 <a class="header-anchor" href="#rtorrent的功能" aria-label="Permalink to “rTorrent的功能”">​</a></h4><p>一些有用的快捷键和使用方法</p><ul><li>CTRL+ q – 退出rTorrent应用程序</li><li>CTRL+ s – 开始下载</li><li>CTRL+ d – 停止运行中的下载或者移除已完成的下载</li><li>CTRL+ k – 停止并关闭运行中的下载</li><li>CTRL+ r – 在上传/下载种子之前进行Hash检查</li><li>CTRL+ q – 执行两次这个命令，rTorrent会直接退出而不发送“停止”信号</li><li>Left Arrow Key – 跳到上一屏幕</li><li>Right Arrow Key – 跳到下一屏幕</li></ul><h3 id="_2-wget" tabindex="-1">2. Wget <a class="header-anchor" href="#_2-wget" aria-label="Permalink to “2. Wget”">​</a></h3><p>Wget是GNU项目的一部分，名字由World Wide Web (WWW)衍生而来。Wget是用来递归下载、离线查看本地服务器HTML文件一个很好的工具，它可用于Windows， Mac，以及Linux等大部分平台。Wget能通过HTTP，HTTPS和FTP下载文件。另外，能镜像整个网站，支持代理浏览以及暂停/回复下载使得它更为有用。</p><h4 id="安装wget" tabindex="-1">安装Wget <a class="header-anchor" href="#安装wget" aria-label="Permalink to “安装Wget”">​</a></h4><p>由于是GNU项目的一部分，Wget捆绑在大部分标准Linux发行版中，不再需要独立下载安装。如果默认没有安装，你也可以使用apt或者yum安装。</p><pre><code># apt­-get install wget        (基于 APT 的系统)
</code></pre><hr><pre><code># yum install wget        (基于 YUM 的系统)
</code></pre><h4 id="wget的一些基本用法" tabindex="-1">Wget的一些基本用法 <a class="header-anchor" href="#wget的一些基本用法" aria-label="Permalink to “Wget的一些基本用法”">​</a></h4><p>使用wget下载一个单独的文件.</p><pre><code># wget http://www.website-name.com/file
</code></pre><p>递归下载整个网站.</p><pre><code># wget -r http://www.website-name.com
</code></pre><p>从一个网站下载指定类型的文件(例如 pdf 和 png).</p><pre><code># wget -r -A png,pdf http://www.website-name.com
</code></pre><p>Wget是一个很棒的工具，它允许在资源有限的机器上自定义或者过滤下载。这是镜像一个网站(Yahoo.com)的wget下载截图。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Wget.jpeg" alt="Wget 下载文件"></p><p><em>Wget 命令行文件下载</em></p>`,35)),i("p",null,[e[1]||(e[1]=t("要获取更多wget下载的例子，可以阅读我们的文章",-1)),n(r,{href:"https://linux.cn/article-4129-1.html"},{default:a(()=>[...e[0]||(e[0]=[t("Wget下载命令例子",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[17]||(e[17]=l(`<h3 id="_3-curl" tabindex="-1">3. cURL <a class="header-anchor" href="#_3-curl" aria-label="Permalink to “3. cURL”">​</a></h3><p>cURL是在多种协议上传输数据的命令行工具。cURL是支持FTP, HTTP, FTPS, TFTP, TELNET, IMAP, POP3等协议的客户端应用。cURL是一个不同于wget 的简单下载器，和其它的相比，它支持LDAP，POP3。cURL也很好的支持代理下载，暂停下载以及恢复下载。</p><h4 id="安装curl" tabindex="-1">安装cURL <a class="header-anchor" href="#安装curl" aria-label="Permalink to “安装cURL”">​</a></h4><p>在软件仓库或者已安装软件中，cURL在大部分发行版中默认是可用的。如果没有安装，运行apt或者yum从软件仓库中获取需要的安装包。</p><pre><code># apt­-get install curl        (基于 APT 的系统)
</code></pre><hr><pre><code># yum install curl        (基于 YUM 的系统)
</code></pre><p>cURL的基本使用方法</p><pre><code># curl www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl.jpeg" alt="Curl 下载"></p><p><em>Curl 下载</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl-2.jpeg" alt="Curl 下载数据"></p><p><em>Curl 下载</em></p><h3 id="_4-w3m" tabindex="-1">4. w3m <a class="header-anchor" href="#_4-w3m" aria-label="Permalink to “4. w3m”">​</a></h3><p>W3m是GPL协议下发布的基于文本的web浏览器。W3m支持表格，帧，颜色，SSL连接以及内联图像。W3m以快速浏览而出名。</p><h4 id="安装w3m" tabindex="-1">安装w3m <a class="header-anchor" href="#安装w3m" aria-label="Permalink to “安装w3m”">​</a></h4><p>W3m在大部分Linux发行版中也是默认可用的。如果不可用的话可以用apt或者yum获取需要的安装包。</p><pre><code># apt­-get install w3m        (基于 APT 的系统)
</code></pre><hr><pre><code># yum install w3m        (基于 YUM 的系统)
</code></pre><h4 id="w3m的基本使用方法" tabindex="-1">w3m的基本使用方法 <a class="header-anchor" href="#w3m的基本使用方法" aria-label="Permalink to “w3m的基本使用方法”">​</a></h4><pre><code># w3m www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/w3m.jpeg" alt="命令行浏览器"></p><p><em>基于文本的web浏览器w3m</em></p><h3 id="_5-elinks" tabindex="-1">5. Elinks <a class="header-anchor" href="#_5-elinks" aria-label="Permalink to “5. Elinks”">​</a></h3><p>Elinks是基于文本的免费浏览器，用于Unix及基于Unix的系统。Elinks支持 HTTP，HTTP Cookies以及支持浏览Perl和Ruby脚本（LCTT 译注：应该是指 CGI）。也很好的支持选项卡浏览。最棒的是它支持鼠标、彩色以及支持一系列的协议，例如HTTP, FTP, SMB, Ipv4 和 Ipv6。</p><h4 id="安装elinks" tabindex="-1">安装Elinks <a class="header-anchor" href="#安装elinks" aria-label="Permalink to “安装Elinks”">​</a></h4><p>Elinks在大部分Linux发行版上是默认可用的。如果不是的话，可以通过apt或者yum安装。</p><pre><code># apt­-get install elinks    (基于 APT 的系统)
</code></pre><hr><pre><code># yum install elinks        (基于 YUM 的系统)
</code></pre><p>Elinks的基本使用方法</p><pre><code># elinks www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Elinks.jpeg" alt="命令行互联网浏览"></p><p><em>Elinks命令行浏览互联网</em></p><p>就是这些了。有你们喜欢读的有趣的文章，我会再次来到这里。到那时尽请关注并保持和Tecmint的联系，别忘了在评论部分给我们你的宝贵的反馈。</p><hr>`,37)),i("p",null,[e[4]||(e[4]=t("via: ",-1)),n(r,{href:"http://www.tecmint.com/linux-command-line-tools-for-downloading-files/"},{default:a(()=>[...e[3]||(e[3]=[t("http://www.tecmint.com/linux-command-line-tools-for-downloading-files/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=t("作者：",-1)),n(r,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[5]||(e[5]=[t("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),n(r,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[6]||(e[6]=[t("ictlyh",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:a(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),n(r,{href:"http://linux.cn/"},{default:a(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const P=o(m,[["render",w]]);export{f as __pageData,P as default};
